            'afternoon': 'Добрый день (Dobryy den')',
            'evening': 'Добрый вечер (Dobryy vecher)',
            'night': 'Спокойной ночи (Spokoynoy nochey)'
        },
        'AR': {
            'morning': 'صباح الخير (Sabah al-khair)',
            'afternoon': 'مساء الخير (Masa' al-khair)',
            'evening': 'مساء الخير (Masa' al-khair)',
            'night': 'تصبح على خير (Tusbih 'ala khair)'
        },
        'HI': {
            'morning': 'सुप्रभातम् (Suprabhātam)',
            'afternoon': 'नमस्ते (Namaste)',
            'evening': 'शुभ रात्रि (Shubh Raatri)',
            'night': 'अच्छी रात्रि (Achchhii Raatri)'
        }
    }

    if country_code in cultural_greetings:
        greetings = cultural_greetings[country_code]
        if 5 <= local_hour < 12:
            return greetings['morning']
        elif 12 <= local_hour < 17:
            return greetings['afternoon']
        elif 17 <= local_hour < 21:
            return greetings['evening']
        else:
            return greetings['night']
    else:
        # Default to English time-based greeting
        return get_time_based_greeting(local_hour)

def smart_greeting():
    """Main function to generate smart greeting"""
