## Approach 2: Browser-Based Geolocation

For web applications, you can use the browser's geolocation API:

```javascript
// Frontend JavaScript
function getSmartGreeting() {
    return new Promise((resolve, reject) => {
        if (!navigator.geolocation) {
            // Fallback to IP-based geolocation
            fetch('/api/greeting-by-ip')
                .then(response => response.json())
                .then(data => resolve(data))
                .catch(error => reject(error));
            return;
        }

        navigator.geolocation.getCurrentPosition(
            async (position) => {
                try {
                    const { latitude, longitude } = position.coords;
                    const response = await fetch(`/api/greeting?lat=${latitude}&lon=${longitude}`);
                    const data = await response.json();
                    resolve(data);
                } catch (error) {
                    reject(error);
                }
            },
            (error) => {
                // Fallback to IP-based geolocation on error
                fetch('/api/greeting-by-ip')
                    .then(response => response.json())
                    .then(data => resolve(data))
                    .catch(err => reject(err));
            }
        );
    });
}

// Usage
getSmartGreeting()
    .then(data => {
        console.log(`Greeting: ${data.greeting}`);
        console.log(`Location: ${data.location}`);
        displayGreeting(data.greeting);
    })
    .catch(error => {
        console.error('Error getting greeting:', error);
        displayGreeting('Hello'); // Fallback greeting
    });
```

## Approach 3: Enhanced Python Backend with Fallback Strategy

Here's a more robust backend implementation with multiple fallback strategies:

```python
import requests
import json
from datetime import datetime
import pytz
from typing import Dict, Optional

class SmartGreetingService:
    def __init__(self):
        self.ip_geolocation_services = [
            'https://ipapi.co/json/',
            'http://ip-api.com/json/',
            'https://freegeoip.app/json/'
        ]

        self.cultural_greetings = self._load_cultural_greetings()

        # Time thresholds for different greetings
        self.time_periods = {
            'morning': (5, 12),
            'afternoon': (12, 17),
            'evening': (17, 21),
            'night': (21, 24)
        }

    def _load_cultural_greetings(self) -> Dict:
        """Load cultural greetings data"""
        return {
            'JP': {
                'morning': 'おはようございます',
                'afternoon': 'こんにちは',
                'evening': 'こんばんは',
                'night': 'おやすみなさい'
            },
            'KR': {
                'morning': '좋은 아침입니다',
                'afternoon': '안녕하세요',
                'evening': '안녕하세요',
                'night': '안녕히 주무세요'
            },
            # Add more countries as needed...
            'US': {
                'morning': 'Good morning',
                'afternoon': 'Good afternoon',
                'evening': 'Good evening',
                'night': 'Good night'
            }
        }

    def get_location_from_ip(self, ip_address: Optional[str] = None) -> Dict:
        """Get location from IP address using multiple services"""
        for service_url in self.ip_geolocation_services:
            try:
                url = service_url if not ip_address else service_url.replace('/json/', f'/json/{ip_address}')
                response = requests.get(url, timeout=5)
                data = response.json()

                return {
                    'country': data.get('country_name') or data.get('country', 'Unknown'),
                    'country_code': data.get('country_code', '').upper(),
                    'timezone': data.get('timezone', 'UTC'),
                    'region': data.get('regionName') or data.get('region', ''),
                    'city': data.get('city', '')
                }
            except Exception as e:
                continue

        # Return default values if all services fail
        return {
            'country': 'Unknown',
            'country_code': '',
            'timezone': 'UTC',
            'region': '',
            'city': ''
        }

    def get_local_time(self, timezone_str: str) -> datetime:
        """Get local time based on timezone string"""
        try:
            if timezone_str and timezone_str != 'UTC':
                tz = pytz.timezone(timezone_str)
                return datetime.now(tz)
        except:
            pass
        return datetime.now()

    def determine_time_period(self, hour: int) -> str:
        """Determine time period based on hour"""
        if 5 <= hour < 12:
            return 'morning'
        elif 12 <= hour < 17:
            return 'afternoon'
        elif 17 <= hour < 21:
            return 'evening'
        else:
            return 'night'

    def get_greeting(self, country_code: str, time_period: str) -> str:
        """Get appropriate greeting based on country and time period"""
        # Check if we have cultural greetings for this country
        if country_code in self.cultural_greetings:
            return self.cultural_greetings[country_code].get(time_period, 
                   self.cultural_greetings['US'][time_period])

        # Default to US/English greetings
        default_greetings = {
            'morning': 'Good morning',
            'afternoon': 'Good afternoon',
            'evening': 'Good evening',
            'night': 'Good night'
        }
        return default_greetings[time_period]

    def generate_smart_greeting(self, ip_address: Optional[str] = None) -> Dict:
        """Main function to generate smart greeting"""
        # Get location information
        location = self.get_location_from_ip(ip_address)

        # Get local time
        local_time = self.get_local_time(location['timezone'])
        local_hour = local_time.hour

        # Determine time period
        time_period = self.determine_time_period(local_hour)

        # Get appropriate greeting
        greeting = self.get_greeting(location['country_code'], time_period)

        # Add English translation for better UX
        english_greeting = self.get_greeting('US', time_period)

        return {
