            margin-bottom: 5px;
            font-weight: 500;
            color: #333;
        }

        input, textarea {
            width: 100%;
            padding: 12px;
            border: 2px solid #ddd;
            border-radius: 4px;
            font-size: 16px;
            transition: border-color 0.3s;
        }

        input:focus, textarea:focus {
            outline: none;
            border-color: #4CAF50;
        }

        /* Typing animation */
        .typing-dots {
            display: none;
            margin-left: 10px;
            font-size: 14px;
        }

        .typing-dots::after {
            content: '...';
            animation: ellipsis 1.5s infinite;
        }

        @keyframes ellipsis {
            0% { content: '.'; }
            33% { content: '..'; }
            66% { content: '...'; }
            100% { content: '.'; }
        }

        /* Form button */
        button {
            background-color: #4CAF50;
            color: white;
            padding: 12px 20px;
            border: none;
            border-radius: 4px;
            cursor: pointer;
            font-size: 16px;
        }

        button:hover {
            background-color: #45a049;
        }
    </style>
</head>
<body>
    <h1>Form with Typing Animation</h1>

    <form id="myForm">
        <div class="form-group">
            <label for="name">Name:</label>
            <input type="text" id="name" placeholder="Enter your name">
        </div>

        <div class="form-group">
            <label for="email">Email:</label>
            <input type="email" id="email" placeholder="Enter your email">
        </div>

        <div class="form-group">
            <label for="message">Message:</label>
            <textarea id="message" rows="5" placeholder="Enter your message"></textarea>
        </div>

        <button type="submit">Submit</button>
    </form>

    <script>
        document.querySelectorAll('input, textarea').forEach(input => {
            // Create typing indicator element
            const typingIndicator = document.createElement('span');
            typingIndicator.className = 'typing-dots';
            typingIndicator.textContent = 'Typing';
            input.parentNode.appendChild(typingIndicator);

            let typingTimer;

            // Function to show typing indicator
            function showTypingIndicator() {
                clearTimeout(typingTimer);
                typingIndicator.style.display = 'inline-block';
                input.style.borderColor = '#4CAF50';
            }

            // Function to hide typing indicator
            function hideTypingIndicator() {
                clearTimeout(typingTimer);
                typingTimer = setTimeout(() => {
                    typingIndicator.style.display = 'none';
                    input.style.borderColor = '#ddd';
                }, 1500);
            }

            // Event listeners
            input.addEventListener('input', showTypingIndicator);
            input.addEventListener('blur', hideTypingIndicator);
        });

        // Form submission handler
        document.getElementById('myForm').addEventListener('submit', function(e) {
            e.preventDefault();
            alert('Form submitted successfully!');
        });
    </script>
</body>
</html>
```

Key features of this implementation:

1. **Typing Indicator**: Shows animated dots (...) when users are typing
2. **Visual Feedback**: Input borders turn green during typing
3. **Auto-Hide**: Indicator disappears after 1.5 seconds of inactivity
4. **Responsive Design**: Works on different screen sizes
5. **Clean UI**: Modern styling with smooth transitions

To use this in your project:

1. Copy the CSS into your stylesheet
2. Add the JavaScript to your script file
3. Apply the classes to your form elements

Customization options:

- Change the color by modifying `#4CAF50` values
- Adjust timing by changing the `1500` ms timeout value
- Modify the animation speed by editing the `1.5s` duration in CSS

The animation activates whenever users start typing in any input field and provides immediate visual feedback, improving the overall user experience.

